/// DDL for Module Utilisateur.
///
/// Called once from [DatabaseHelper._onCreate].
/// To add a column or table to this module, create a new migration file
/// (e.g. migration_v2_user.dart), bump [DatabaseHelper._dbVersion], and
/// handle it in [DatabaseHelper._onUpgrade].  Do NOT edit this file after
/// the schema is frozen and the app has shipped.
library;

import 'package:sqflite/sqflite.dart';

class UserModuleTables {
  UserModuleTables._();

  static Future<void> create(DatabaseExecutor db) async {
    // ── users ──────────────────────────────────────────────────────────────
    await db.execute('''
      CREATE TABLE IF NOT EXISTS users (
        id                  INTEGER PRIMARY KEY AUTOINCREMENT,
        email               TEXT    NOT NULL UNIQUE,
        password_hash       TEXT    NOT NULL,
        salt                TEXT    NOT NULL,
        password_iterations INTEGER NOT NULL,
        user_type           TEXT    NOT NULL DEFAULT 'client'
                              CHECK(user_type IN ('client','restaurant')),
        is_active           INTEGER NOT NULL DEFAULT 1
                              CHECK(is_active IN (0,1)),
        reset_question      TEXT    NULL,
        reset_answer_hash   TEXT    NULL,
        reset_answer_salt   TEXT    NULL,
        created_at          TEXT    NOT NULL
                              DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')),
        updated_at          TEXT    NOT NULL
                              DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now'))
      )
    ''');

    // ── client_profiles ────────────────────────────────────────────────────
    await db.execute('''
      CREATE TABLE IF NOT EXISTS client_profiles (
        id                  INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id             INTEGER NOT NULL UNIQUE,
        full_name           TEXT    NULL,
        phone               TEXT    NULL,
        photo_path          TEXT    NULL,
        dietary_preferences TEXT    NULL,
        allergies           TEXT    NULL,
        created_at          TEXT    NOT NULL
                              DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')),
        updated_at          TEXT    NOT NULL
                              DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')),
        FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
      )
    ''');

    // ── restaurant_profiles ────────────────────────────────────────────────
    await db.execute('''
      CREATE TABLE IF NOT EXISTS restaurant_profiles (
        id            INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id       INTEGER NOT NULL UNIQUE,
        name          TEXT    NOT NULL
                        CHECK(length(trim(name)) > 0),
        address       TEXT    NULL,
        latitude      REAL    NULL,
        longitude     REAL    NULL,
        opening_hours TEXT    NULL,
        cuisine_type  TEXT    NULL,
        photo_paths   TEXT    NULL,
        description   TEXT    NULL,
        created_at    TEXT    NOT NULL
                        DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')),
        updated_at    TEXT    NOT NULL
                        DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')),
        FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
      )
    ''');

    // ── favorite_restaurants ───────────────────────────────────────────────
    await db.execute('''
      CREATE TABLE IF NOT EXISTS favorite_restaurants (
        id            INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id       INTEGER NOT NULL,
        restaurant_id INTEGER NOT NULL,
        created_at    TEXT    NOT NULL
                        DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')),
        UNIQUE(user_id, restaurant_id),
        FOREIGN KEY (user_id)
          REFERENCES users(id)               ON DELETE CASCADE,
        FOREIGN KEY (restaurant_id)
          REFERENCES restaurant_profiles(id) ON DELETE CASCADE
      )
    ''');

    // ── favorite_dishes ────────────────────────────────────────────────────
    await db.execute('''
      CREATE TABLE IF NOT EXISTS favorite_dishes (
        id         INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id    INTEGER NOT NULL,
        dish_id    INTEGER NOT NULL,
        created_at TEXT    NOT NULL
                     DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')),
        UNIQUE(user_id, dish_id),
        FOREIGN KEY (user_id)  REFERENCES users(id)   ON DELETE CASCADE,
        FOREIGN KEY (dish_id)  REFERENCES dishes(id)  ON DELETE CASCADE
      )
    ''');
  }
}
